package com.company.platform.administration.domain;import java.time.Instant;import java.util.*;public record AdministrationUser(UUID id,UUID tenantId,String externalUserId,String status,String configuration,Instant createdAt,Instant updatedAt){public AdministrationUser{if(id==null||tenantId==null||externalUserId==null||externalUserId.isBlank()||status==null||configuration==null||createdAt==null||updatedAt==null)throw new IllegalArgumentException("invalid administration user");}public static AdministrationUser create(UUID tenantId,String externalUserId,String configuration){Instant now=Instant.now();return new AdministrationUser(UUID.randomUUID(),tenantId,externalUserId,"ACTIVE",configuration,now,now);}}
